import { evaluateMergeDecision, type MergeCandidate } from '../src/mergeDecision';

const mergeable = (overrides: Partial<MergeCandidate> = {}): MergeCandidate => ({
	state: 'open',
	draft: false,
	merged: false,
	mergeable: true,
	mergeableState: 'clean',
	readyToMerge: true,
	reviewsSatisfied: true,
	...overrides,
});

describe('evaluateMergeDecision', () => {
	test('merges a PR that satisfies everything', () => {
		expect(evaluateMergeDecision(mergeable())).toEqual({ merge: true });
	});

	test.each([
		['already-merged', { merged: true }],
		['pr-not-open', { state: 'closed' }],
		['draft', { draft: true }],
		['mergeability-unknown', { mergeable: null }],
		['conflicts', { mergeable: false }],
		['conflicts', { mergeableState: 'dirty' }],
		['reviews', { reviewsSatisfied: false }],
		['qa-not-ready', { readyToMerge: false }],
	])('refuses with reason %s', (reason, overrides) => {
		expect(evaluateMergeDecision(mergeable(overrides as Partial<MergeCandidate>))).toEqual({ merge: false, reason });
	});

	// The state the bot used to merge on: QA passed earlier, conditions changed, nothing re-ran.
	test('refuses a PR whose review was dismissed after QA passed', () => {
		expect(evaluateMergeDecision(mergeable({ reviewsSatisfied: false, readyToMerge: true }))).toEqual({ merge: false, reason: 'reviews' });
	});

	test('refuses when the base branch moved and left conflicts', () => {
		expect(evaluateMergeDecision(mergeable({ mergeable: false, mergeableState: 'dirty' }))).toEqual({ merge: false, reason: 'conflicts' });
	});

	test('never merges on a mergeability GitHub has not finished computing', () => {
		expect(evaluateMergeDecision(mergeable({ mergeable: null, mergeableState: 'unknown' }))).toEqual({
			merge: false,
			reason: 'mergeability-unknown',
		});
	});
});

export type MergeDecision = { merge: true } | { merge: false; reason: MergeSkipReason };

export type MergeSkipReason =
	| 'already-merged'
	| 'pr-not-open'
	| 'draft'
	| 'mergeability-unknown'
	| 'conflicts'
	| 'reviews'
	| 'qa-not-ready';

export interface MergeCandidate {
	state: string;
	draft: boolean;
	merged: boolean;
	mergeable: boolean | null;
	mergeableState: string;
	readyToMerge: boolean;
	reviewsSatisfied: boolean;
}

/**
 * Decides whether a pull request may be merged, from a snapshot taken just now.
 *
 * Pure on purpose: the merge used to be authorised by whatever conclusion the check run happened
 * to be storing, which could have been computed hours earlier under different conditions.
 * The `reason` is logged, so "why did it not merge?" is answerable without reproducing the state.
 */
export const evaluateMergeDecision = (pr: MergeCandidate): MergeDecision => {
	if (pr.merged) {
		return { merge: false, reason: 'already-merged' };
	}

	if (pr.state !== 'open') {
		return { merge: false, reason: 'pr-not-open' };
	}

	if (pr.draft) {
		return { merge: false, reason: 'draft' };
	}

	// Never act on a mergeability GitHub has not finished computing.
	if (pr.mergeable === null) {
		return { merge: false, reason: 'mergeability-unknown' };
	}

	if (!pr.mergeable || pr.mergeableState === 'dirty') {
		return { merge: false, reason: 'conflicts' };
	}

	if (!pr.reviewsSatisfied) {
		return { merge: false, reason: 'reviews' };
	}

	if (!pr.readyToMerge) {
		return { merge: false, reason: 'qa-not-ready' };
	}

	return { merge: true };
};

import { resolvePullRequestForHead } from '../src/resolvePullRequest';
import type { Log } from '../src/logger';

const silentLog = { debug() {}, info() {}, warn() {}, error() {} } as unknown as Log;

const HEAD_SHA = 'aaaaaaa';
const EVENT = { owner: 'RocketChat', repo: 'Rocket.Chat' };

const pr = (number: number, overrides: Record<string, unknown> = {}) => ({
	number,
	state: 'open',
	head: { sha: HEAD_SHA },
	base: { repo: { name: 'Rocket.Chat', owner: { login: 'RocketChat' } } },
	...overrides,
});

const octokitWith = ({
	get,
	associated,
	list,
}: {
	get?: (n: number) => unknown;
	associated?: unknown[];
	list?: unknown[];
}) =>
	({
		pulls: {
			get: async ({ pull_number }: { pull_number: number }) => {
				if (!get) throw new Error('not found');
				return { data: get(pull_number) };
			},
			list: {},
		},
		repos: {
			listPullRequestsAssociatedWithCommit: async () => {
				if (!associated) throw new Error('commit not in this repo');
				return { data: associated };
			},
		},
		paginate: async () => list ?? [],
	}) as never;

const resolve = (octokit: never, hints: { number: number }[] = [], branch: string | null = 'feature') =>
	resolvePullRequestForHead(octokit, EVENT, HEAD_SHA, branch, hints, silentLog);

describe('resolvePullRequestForHead', () => {
	test('uses the check suite hint when it matches the head sha', async () => {
		const result = await resolve(octokitWith({ get: (n) => pr(n) }), [{ number: 42 }]);

		expect(result).toEqual({ number: 42, baseOwner: 'RocketChat', baseRepo: 'Rocket.Chat' });
	});

	test('ignores a hint whose head has moved on', async () => {
		const octokit = octokitWith({
			get: (n) => pr(n, { head: { sha: 'stale' } }),
			associated: [pr(7)],
		});

		expect(await resolve(octokit, [{ number: 42 }])).toMatchObject({ number: 7 });
	});

	test('ignores a hint for a closed pull request', async () => {
		const octokit = octokitWith({
			get: (n) => pr(n, { state: 'closed' }),
			associated: [pr(7)],
		});

		expect(await resolve(octokit, [{ number: 42 }])).toMatchObject({ number: 7 });
	});

	// Fork PRs: check_suite carries no head_branch, and the head commit is only reachable
	// through the base repository's network.
	test('resolves a fork pull request via commit association', async () => {
		const octokit = octokitWith({ associated: [pr(99)] });

		expect(await resolve(octokit, [], null)).toMatchObject({ number: 99 });
	});

	test('carries the base repository across from a fork', async () => {
		const forked = pr(99, { base: { repo: { name: 'Rocket.Chat', owner: { login: 'RocketChat' } } } });
		const result = await resolve(octokitWith({ associated: [forked] }), [], null);

		expect(result).toEqual({ number: 99, baseOwner: 'RocketChat', baseRepo: 'Rocket.Chat' });
	});

	// The invariant: several open PRs can share a head branch name, only one has this commit.
	test('picks the pull request whose tip is the head sha, not the most recent', async () => {
		const octokit = octokitWith({
			list: [pr(1, { head: { sha: 'other' } }), pr(2), pr(3, { head: { sha: 'another' } })],
		});

		expect(await resolve(octokit)).toMatchObject({ number: 2 });
	});

	test('returns null for a superseded sha rather than guessing', async () => {
		const octokit = octokitWith({ list: [pr(1, { head: { sha: 'newer' } })] });

		expect(await resolve(octokit)).toBeNull();
	});

	test('returns null when nothing matches at all', async () => {
		expect(await resolve(octokitWith({}), [], null)).toBeNull();
	});
});

import { maxBumpForMilestone, parseChangesetBumps, findInvalidBumps, titleIndicatesBreaking, findChangesetProblems } from '../src/checkChangesets';
import type { Bump } from '../src/checkChangesets';

describe('maxBumpForMilestone', () => {
	test('patch milestone only allows patch', () => {
		expect(maxBumpForMilestone('7.10.1')).toBe('patch');
		expect(maxBumpForMilestone('6.5.11')).toBe('patch');
	});

	test('minor milestone allows up to minor', () => {
		expect(maxBumpForMilestone('7.10.0')).toBe('minor');
		expect(maxBumpForMilestone('7.10')).toBe('minor');
	});

	test('major milestone allows up to major', () => {
		expect(maxBumpForMilestone('8.0.0')).toBe('major');
		expect(maxBumpForMilestone('8.0')).toBe('major');
	});

	test('non-version milestones impose no restriction', () => {
		expect(maxBumpForMilestone('Backlog')).toBeNull();
		expect(maxBumpForMilestone(undefined)).toBeNull();
		expect(maxBumpForMilestone('')).toBeNull();
	});
});

describe('parseChangesetBumps', () => {
	test('parses single package', () => {
		expect(parseChangesetBumps("---\n'@rocket.chat/meteor': patch\n---\n\nFix something\n")).toEqual(['patch']);
	});

	test('parses multiple packages and quote styles', () => {
		const content = ['---', "'@rocket.chat/meteor': minor", '"@rocket.chat/ui-client": patch', '@rocket.chat/core: major', '---', '', 'desc'].join(
			'\n',
		);
		expect(parseChangesetBumps(content)).toEqual(['minor', 'patch', 'major']);
	});

	test('handles CRLF', () => {
		expect(parseChangesetBumps("---\r\n'@rocket.chat/meteor': minor\r\n---\r\ndesc")).toEqual(['minor']);
	});

	test('no frontmatter means no bumps', () => {
		expect(parseChangesetBumps('just a description')).toEqual([]);
		expect(parseChangesetBumps('')).toEqual([]);
	});

	test('ignores bump-like words outside frontmatter', () => {
		expect(parseChangesetBumps("---\n'@rocket.chat/meteor': patch\n---\n\nthis is a major: change")).toEqual(['patch']);
	});
});

describe('findInvalidBumps', () => {
	const files = [
		{ filename: '.changeset/one.md', bumps: ['patch'] as const },
		{ filename: '.changeset/two.md', bumps: ['minor', 'patch'] as const },
		{ filename: '.changeset/three.md', bumps: ['major'] as const },
	].map((f) => ({ ...f, bumps: [...f.bumps] }));

	test('patch milestone flags minor and major changesets', () => {
		expect(findInvalidBumps(files, 'patch')).toEqual([
			{ filename: '.changeset/two.md', invalid: ['minor'] },
			{ filename: '.changeset/three.md', invalid: ['major'] },
		]);
	});

	test('minor milestone flags only major changesets', () => {
		expect(findInvalidBumps(files, 'minor')).toEqual([{ filename: '.changeset/three.md', invalid: ['major'] }]);
	});

	test('major milestone flags nothing', () => {
		expect(findInvalidBumps(files, 'major')).toEqual([]);
	});
});

describe('titleIndicatesBreaking', () => {
	test('detects conventional-commit breaking marker', () => {
		expect(titleIndicatesBreaking('feat!: drop legacy API')).toBe(true);
		expect(titleIndicatesBreaking('feat(core)!: drop legacy API')).toBe(true);
	});

	test('regular titles are not breaking', () => {
		expect(titleIndicatesBreaking('feat: add thing')).toBe(false);
		expect(titleIndicatesBreaking('fix(core): oops')).toBe(false);
		expect(titleIndicatesBreaking('Wow! great PR')).toBe(false);
		expect(titleIndicatesBreaking(undefined)).toBe(false);
	});
});

describe('findChangesetProblems', () => {
	const major = [{ filename: '.changeset/big.md', bumps: ['major'] as Bump[] }];
	const patch = [{ filename: '.changeset/small.md', bumps: ['patch'] as Bump[] }];

	test('breaking title requires at least one major changeset', () => {
		expect(findChangesetProblems(patch, '8.0.0', 'feat!: breaking')).toHaveLength(1);
		expect(findChangesetProblems([], '8.0.0', 'feat!: breaking')).toHaveLength(1);
		expect(findChangesetProblems(major, '8.0.0', 'feat!: breaking')).toEqual([]);
	});

	test('major changeset requires breaking title', () => {
		expect(findChangesetProblems(major, '8.0.0', 'feat: not breaking')).toHaveLength(1);
	});

	test('milestone and title problems are both reported', () => {
		expect(findChangesetProblems(major, '7.10.1', 'feat: not breaking')).toHaveLength(2);
	});

	test('aligned patch PR has no problems', () => {
		expect(findChangesetProblems(patch, '7.10.1', 'fix: something')).toEqual([]);
	});
});

import { summarizeReviews } from '../src/reviews';

const review = (login: string, state: string, type = 'User') => ({ user: { login, type }, state });

describe('summarizeReviews', () => {
	test('an approval satisfies the gate', () => {
		expect(summarizeReviews([review('alice', 'APPROVED')])).toEqual({
			approvals: ['alice'],
			changesRequested: [],
			satisfied: true,
		});
	});

	// The hole this closes: a drive-by comment used to count as "reviewed" and unlock the merge.
	test('a comment-only review does not satisfy the gate', () => {
		expect(summarizeReviews([review('alice', 'COMMENTED')]).satisfied).toBe(false);
	});

	// And this one: CHANGES_REQUESTED is itself a review, so it used to count as "reviewed" too.
	test('an outstanding changes-requested blocks, even alongside an approval', () => {
		const summary = summarizeReviews([review('alice', 'APPROVED'), review('bob', 'CHANGES_REQUESTED')]);

		expect(summary.changesRequested).toEqual(['bob']);
		expect(summary.satisfied).toBe(false);
	});

	test('only the latest position per reviewer counts', () => {
		expect(summarizeReviews([review('bob', 'CHANGES_REQUESTED'), review('bob', 'APPROVED')]).satisfied).toBe(true);
	});

	test('a later comment does not withdraw an earlier objection', () => {
		const summary = summarizeReviews([review('alice', 'APPROVED'), review('bob', 'CHANGES_REQUESTED'), review('bob', 'COMMENTED')]);

		expect(summary.satisfied).toBe(false);
	});

	test('a dismissed approval no longer counts', () => {
		expect(summarizeReviews([review('alice', 'APPROVED'), review('alice', 'DISMISSED')]).satisfied).toBe(false);
	});

	test('a dismissed changes-requested stops blocking', () => {
		const summary = summarizeReviews([review('alice', 'APPROVED'), review('bob', 'CHANGES_REQUESTED'), review('bob', 'DISMISSED')]);

		expect(summary.satisfied).toBe(true);
	});

	test('bot reviews are ignored', () => {
		const summary = summarizeReviews([review('dionisio-bot[bot]', 'CHANGES_REQUESTED', 'Bot'), review('alice', 'APPROVED')]);

		expect(summary.changesRequested).toEqual([]);
		expect(summary.satisfied).toBe(true);
	});

	test('a pending review is not submitted yet', () => {
		expect(summarizeReviews([review('alice', 'PENDING')]).satisfied).toBe(false);
	});

	test('no reviews at all', () => {
		expect(summarizeReviews([])).toEqual({ approvals: [], changesRequested: [], satisfied: false });
	});
});

import {
	blockedOnlyByMergeability,
	buildCheckVerdict,
	formatCheckRunOutput,
	runQAChecks,
	type PullRequestForQA,
	type QAChecksResult,
	type QAStep,
} from '../src/qaChecks';
import type { Log } from '../src/logger';

const silentLog = { debug() {}, info() {}, warn() {}, error() {} } as unknown as Log;

// runQAChecks only needs `request` (package.json on the base ref) and `graphql` (projects lookup).
const fakeOctokit = (version = '7.10.1') =>
	({
		request: async () => ({ data: JSON.stringify({ version }) }),
		graphql: async () => ({ totalCount: { projectsV2: { totalCount: 0 } } }),
	}) as never;

const prForQA = (overrides: Partial<PullRequestForQA> = {}): PullRequestForQA => ({
	mergeable: true,
	draft: false,
	labels: [{ name: 'stat: QA assured' }],
	mergeable_state: 'clean',
	milestone: '7.10.1',
	url: 'https://github.com/o/r/pull/1',
	number: 1,
	title: 'fix: something',
	...overrides,
});

const step = (name: string, passed: boolean): QAStep => ({ name, passed });

const approved = { approvals: ['alice'], changesRequested: [], satisfied: true };
const unreviewed = { approvals: [], changesRequested: [], satisfied: false };
const blocked = { approvals: ['alice'], changesRequested: ['bob'], satisfied: false };

const result = (overrides: Partial<QAChecksResult> = {}): QAChecksResult => {
	const steps = overrides.steps ?? [
		step('Ready for review', true),
		step('No merge conflicts', true),
		step('QA assured', true),
		step('Mergeable', true),
		step('Has milestone or project', true),
		step('Valid PR title', true),
		step('Correct target version', true),
	];

	return {
		steps,
		readyToMerge: steps.every((s) => s.passed),
		hasConflicts: false,
		assured: true,
		mergeable: true,
		mergeabilityUnknown: false,
		isDraft: false,
		hasMilestone: true,
		hasInvalidTitle: false,
		targetingVersion: [],
		originalLabels: [],
		currentLabels: [],
		newLabels: [],
		...overrides,
	};
};

describe('runQAChecks', () => {
	const run = (pr: Partial<PullRequestForQA>) => runQAChecks(prForQA(pr), 'o', 'r', 'develop', fakeOctokit(), silentLog);

	test('a clean, assured, milestoned PR is ready to merge', async () => {
		const qa = await run({});

		expect(qa?.readyToMerge).toBe(true);
		expect(qa?.steps.every((s) => s.passed)).toBe(true);
	});

	// The original defect: `mergeable: null` rendered a ✅ step while readyToMerge went false,
	// producing "Conclusion: failure" under an all-green step list.
	test('unknown mergeability never yields a passing step', async () => {
		const qa = await run({ mergeable: null });

		expect(qa?.mergeabilityUnknown).toBe(true);
		expect(qa?.steps.find((s) => s.name === 'Mergeable')?.passed).toBe(false);
		expect(qa?.readyToMerge).toBe(false);
	});

	test('a draft is not ready to merge', async () => {
		const qa = await run({ draft: true });

		expect(qa?.isDraft).toBe(true);
		expect(qa?.readyToMerge).toBe(false);
		expect(qa?.newLabels).not.toContain('stat: ready to merge');
	});

	// Guards the seam the bug lived in: steps and readyToMerge must be one decision.
	test('readyToMerge always equals "every step passed"', async () => {
		const cases: Partial<PullRequestForQA>[] = [
			{},
			{ mergeable: null },
			{ mergeable: false },
			{ draft: true },
			{ mergeable_state: 'dirty' },
			{ labels: [] },
			{ title: 'not a conventional title' },
			{ milestone: undefined },
			{ milestone: '8.0.0' },
		];

		for (const override of cases) {
			const qa = await run(override);

			expect(qa).not.toBeNull();
			expect(qa?.readyToMerge).toBe(qa?.steps.every((s) => s.passed));
		}
	});
});

describe('blockedOnlyByMergeability', () => {
	// Decides whether waiting on GitHub is worth seconds inside a webhook.
	test('true when mergeability is the last thing missing', async () => {
		const qa = await runQAChecks(prForQA({ mergeable: null }), 'o', 'r', 'develop', fakeOctokit(), silentLog);

		expect(blockedOnlyByMergeability(qa!)).toBe(true);
	});

	test('false when something else already fails, so the answer cannot change the outcome', async () => {
		const qa = await runQAChecks(prForQA({ mergeable: null, labels: [] }), 'o', 'r', 'develop', fakeOctokit(), silentLog);

		expect(blockedOnlyByMergeability(qa!)).toBe(false);
	});

	test('false once mergeability is known', async () => {
		const qa = await runQAChecks(prForQA({ mergeable: true }), 'o', 'r', 'develop', fakeOctokit(), silentLog);

		expect(blockedOnlyByMergeability(qa!)).toBe(false);
	});
});

describe('buildCheckVerdict', () => {
	test('a fully passing, reviewed PR succeeds', () => {
		const verdict = buildCheckVerdict(result(), { reviews: approved });

		expect(verdict.conclusion).toBe('success');
		expect(verdict.steps.every((s) => s.passed)).toBe(true);
	});

	test('unknown mergeability is neutral, never a silent pass', () => {
		const steps = result().steps.map((s) => (s.name === 'Mergeable' ? step('Mergeable', false) : s));
		const verdict = buildCheckVerdict(result({ steps, mergeable: false, mergeabilityUnknown: true }), { reviews: approved });

		expect(verdict.conclusion).toBe('neutral');
		expect(verdict.title).toBe('Waiting for GitHub to compute mergeability');
	});

	test('a draft is neutral even when everything else passes', () => {
		const steps = result().steps.map((s) => (s.name === 'Ready for review' ? step('Ready for review', false) : s));
		const verdict = buildCheckVerdict(result({ steps, isDraft: true }), { reviews: approved });

		expect(verdict.conclusion).toBe('neutral');
		expect(verdict.title).toBe('Draft — not ready for review');
	});

	test('an unreviewed PR is neutral and says so in the steps', () => {
		const verdict = buildCheckVerdict(result(), { reviews: unreviewed });

		expect(verdict.conclusion).toBe('neutral');
		expect(verdict.title).toBe('Waiting for reviews');
		expect(verdict.steps.find((s) => s.name === 'Reviewed')?.passed).toBe(false);
	});

	test('a failing step produces failure', () => {
		const steps = result().steps.map((s) => (s.name === 'QA assured' ? step('QA assured', false) : s));
		const verdict = buildCheckVerdict(result({ steps }), { reviews: approved });

		expect(verdict.conclusion).toBe('failure');
	});

	// "Changes requested" must never be printed over an all-green step list — that is the same
	// contradiction the conclusion line used to produce, arriving through the review gate.
	test('changes requested fails and names who is blocking, in the steps', () => {
		const verdict = buildCheckVerdict(result(), { reviews: blocked });

		expect(verdict.conclusion).toBe('failure');
		expect(verdict.title).toBe('Changes requested');

		const reviewed = verdict.steps.find((s) => s.name === 'Reviewed');
		expect(reviewed?.passed).toBe(false);
		expect(reviewed?.message).toContain('bob');
		expect(verdict.steps.every((s) => s.passed)).toBe(false);
	});

	// This is the regression that produced "Conclusion: failure" under six green steps.
	test('conclusion is success if and only if every step passed', () => {
		const names = ['Ready for review', 'No merge conflicts', 'QA assured', 'Mergeable', 'Has milestone or project'];

		for (const failing of [null, ...names]) {
			for (const reviews of [approved, unreviewed, blocked]) {
				const steps = result().steps.map((s) => (s.name === failing ? step(s.name, false) : s));
				const verdict = buildCheckVerdict(
					result({
						steps,
						isDraft: failing === 'Ready for review',
						mergeabilityUnknown: failing === 'Mergeable',
					}),
					{ reviews },
				);

				expect(verdict.conclusion === 'success').toBe(verdict.steps.every((s) => s.passed));
			}
		}
	});
});

describe('formatCheckRunOutput', () => {
	test('the summary reports the emitted conclusion, not a recomputed one', () => {
		const verdict = buildCheckVerdict(result(), { reviews: unreviewed });
		const { title, summary } = formatCheckRunOutput(verdict);

		expect(verdict.conclusion).toBe('neutral');
		expect(summary).toContain('**Conclusion:** neutral');
		expect(summary).not.toContain('**Conclusion:** success');
		expect(title).toBe(verdict.title);
	});

	test('every failing step explains itself', () => {
		const steps = [step('Ready for review', true), { name: 'QA assured', passed: false, message: 'missing label' }];
		const { summary } = formatCheckRunOutput(buildCheckVerdict(result({ steps }), { reviews: approved }));

		expect(summary).toContain('- ✅ **Ready for review**');
		expect(summary).toContain('- ❌ **QA assured** — missing label');
	});
});

import { chooseMergeStrategy, type MergeCapabilities } from '../src/mergeStrategy';

const caps = (overrides: Partial<MergeCapabilities> = {}): MergeCapabilities => ({
	hasMergeQueue: false,
	allowAutoMerge: false,
	mergeableState: 'clean',
	allowDirectSquash: true,
	...overrides,
});

describe('chooseMergeStrategy', () => {
	// The bug: a rejected enqueue used to fall through to a direct squash, bypassing the queue.
	test('a branch with a merge queue always uses the queue', () => {
		expect(chooseMergeStrategy(caps({ hasMergeQueue: true }))).toEqual({ strategy: 'queue' });
	});

	test('never squashes on a merge-queue branch, whatever else is true', () => {
		for (const allowAutoMerge of [true, false]) {
			for (const allowDirectSquash of [true, false]) {
				for (const mergeableState of ['clean', 'blocked', 'behind', 'unstable']) {
					const choice = chooseMergeStrategy(caps({ hasMergeQueue: true, allowAutoMerge, allowDirectSquash, mergeableState }));

					expect(choice).not.toEqual({ strategy: 'squash' });
				}
			}
		}
	});

	test('prefers auto-merge when the repository allows it', () => {
		expect(chooseMergeStrategy(caps({ allowAutoMerge: true }))).toEqual({ strategy: 'auto-merge' });
	});

	// Failing to detect a queue must not be read as "there is no queue".
	test('refuses to squash when the merge queue lookup failed', () => {
		expect(chooseMergeStrategy(caps({ hasMergeQueue: null }))).toEqual({ skip: 'merge-queue-unknown' });
	});

	test('still uses auto-merge when the merge queue lookup failed', () => {
		expect(chooseMergeStrategy(caps({ hasMergeQueue: null, allowAutoMerge: true }))).toEqual({ strategy: 'auto-merge' });
	});

	test('squashes only when nothing else is available and the state is clean', () => {
		expect(chooseMergeStrategy(caps())).toEqual({ strategy: 'squash' });
	});

	test.each(['blocked', 'behind', 'unstable', 'dirty', 'unknown'])('refuses to squash a %s pull request', (mergeableState) => {
		expect(chooseMergeStrategy(caps({ mergeableState }))).toEqual({ skip: 'squash-not-clean' });
	});

	test('respects the kill switch', () => {
		expect(chooseMergeStrategy(caps({ allowDirectSquash: false }))).toEqual({ skip: 'squash-disabled' });
	});
});

